from taf.sbts.oam.coam.admin import admin

from .bts import Bts


class BtsEnb(Bts):
    """ Represents API to eNB BTS. """

    def __init__(self):
        super(BtsEnb, self).__init__()
        self._api = admin()

    def _connect_to(self, config, name, log_dir, timeout, **kwargs):
        if config and config.oam_ip and config.oam_ip.v4:
            self._host = config.oam_ip.v4.split('/')[0]
        else:
            self._host = '192.168.255.129'
        bts_port = 443
        username = 'Nemuadmin'
        password = 'nemuuser'

        self._logger.info(self._CONNECTION_LOG_MSG.format('eNB BTS', self._host, bts_port, username, password))

        self._api.connect_to(bts_host=self._host,
                             bts_port=bts_port,
                             username=username,
                             password=password,
                             name=name,
                             admin_api_log_dir=log_dir,
                             timeout=timeout)

    def _get_active_alarms(self, connection, timeout):
        return self._api.get_active_alarms(connection=connection, timeout=timeout)

    def _disconnect(self, connection):
        self._api.teardown(connection=connection)
